package com.pawsshop.web;
import com.pawsshop.model.*; import com.pawsshop.repo.*; import com.pawsshop.service.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.stream.Collectors;
@RestController @RequestMapping("/api") public class ExtendedController {
 private final PetServiceRepository services; private final PetRepository pets; private final ProductRepository products; private final ShopUserRepository users; private final AppointmentRepository appointments; private final MessageRepository messages; private final MessageService messageService; private final AppointmentWorkflow workflow;
 public ExtendedController(PetServiceRepository s,PetRepository p,ProductRepository pr,ShopUserRepository u,AppointmentRepository a,MessageRepository m,MessageService ms,AppointmentWorkflow w){services=s;pets=p;products=pr;users=u;appointments=a;messages=m;messageService=ms;workflow=w;}
 private ShopUser current(Authentication auth){return users.findByUsername(auth.getName()).orElseThrow(()->new IllegalArgumentException("Account not found"));}
 private void required(String value,String name){if(value==null||value.trim().isEmpty())throw new IllegalArgumentException(name+" is required");}
 private Appointment appointment(Long id){return appointments.findById(id).orElseThrow(()->new IllegalArgumentException("Appointment not found"));}
 private Pet ownedPet(Long id,Long ownerId){Pet p=pets.findById(id).orElseThrow(()->new IllegalArgumentException("Pet not found"));if(!Objects.equals(ownerId,p.getOwnerId()))throw new org.springframework.security.access.AccessDeniedException("Not your pet");return p;}
 @GetMapping("/catalog") public List<Product> catalog(){return products.findAll();}
 @GetMapping("/services") public List<PetService> services(){return services.findAll();}
 @GetMapping("/doctors") public List<Map<String,Object>> doctors(){return users.findAll().stream().filter(u->u instanceof Doctor).map(u->{Doctor d=(Doctor)u;Map<String,Object> m=new LinkedHashMap<>();m.put("id",d.getId());m.put("name",d.getFullName());m.put("specialization",d.getSpecialization());return m;}).collect(Collectors.toList());}
 @PostMapping("/messages") public Message submitMessage(@RequestBody Message m){return messageService.submit(m);}
 @GetMapping("/messages") public List<Message> messages(){return messages.findAll();}
 @PatchMapping("/messages/{id}") public Message resolveMessage(@PathVariable Long id,@RequestBody Map<String,Boolean> body){Message m=messages.findById(id).orElseThrow(()->new IllegalArgumentException("Message not found"));if(body.get("resolved")==null)throw new IllegalArgumentException("resolved is required");m.setResolved(body.get("resolved"));return messages.save(m);}
 @DeleteMapping("/messages/{id}") public void deleteMessage(@PathVariable Long id){messages.deleteById(id);}
 @GetMapping("/admin/services") public List<PetService> adminServices(){return services.findAll();}
 private void validService(PetService s){required(s.getServiceName(),"Service name");if(s.getPrice()==null||s.getPrice().signum()<0||s.getPrice().scale()>2||s.getDuration()<=0)throw new IllegalArgumentException("Enter a non-negative price and a positive duration");}
 @PostMapping("/admin/services") public PetService addService(@RequestBody PetService s){validService(s);s.setId(null);return services.save(s);}
 @PutMapping("/admin/services/{id}") public PetService editService(@PathVariable Long id,@RequestBody PetService s){validService(s);PetService old=services.findById(id).orElseThrow(()->new IllegalArgumentException("Service not found"));if(!old.getClass().equals(s.getClass()))throw new IllegalArgumentException("Service type cannot be changed");s.setId(id);return services.save(s);}
 @DeleteMapping("/admin/services/{id}") public void deleteService(@PathVariable Long id){services.deleteById(id);}
 @GetMapping("/customer/pets") public List<Pet> myPets(Authentication auth){Long id=current(auth).getId();return pets.findAll().stream().filter(p->Objects.equals(p.getOwnerId(),id)).collect(Collectors.toList());}
 private void validatePet(Pet p){required(p.getName(),"Pet name");if(p.getAge()!=null&&p.getAge()<0)throw new IllegalArgumentException("Age cannot be negative");if(p.getWeight()!=null&&p.getWeight().signum()<0)throw new IllegalArgumentException("Weight cannot be negative");}
 @PostMapping("/customer/pets") public Pet addMyPet(@RequestBody Pet p,Authentication auth){validatePet(p);ShopUser owner=current(auth);p.setId(null);p.setOwnerId(owner.getId());p.setOwnerName(owner.getFullName());return pets.save(p);}
 @PutMapping("/customer/pets/{id}") public Pet editMyPet(@PathVariable Long id,@RequestBody Pet p,Authentication auth){ShopUser owner=current(auth);Pet old=ownedPet(id,owner.getId());validatePet(p);if(!old.getClass().equals(p.getClass()))throw new IllegalArgumentException("Pet type cannot be changed");p.setId(id);p.setOwnerId(owner.getId());p.setOwnerName(owner.getFullName());return pets.save(p);}
 @DeleteMapping("/customer/pets/{id}") public void deleteMyPet(@PathVariable Long id,Authentication auth){ownedPet(id,current(auth).getId());if(appointments.findAll().stream().anyMatch(a->Objects.equals(a.getPetId(),id)&&!Arrays.asList("CANCELLED","COMPLETED").contains(a.getStatus())))throw new IllegalArgumentException("Cancel active appointments before deleting this pet");pets.deleteById(id);}
 public static class Booking {public Long petId;public Long serviceId;public Long doctorId;public String date;public String time;}
 @GetMapping("/customer/appointments") public List<Appointment> myAppointments(Authentication auth){Long id=current(auth).getId();return appointments.findAll().stream().filter(a->Objects.equals(id,a.getOwnerId())).collect(Collectors.toList());}
 @PostMapping("/customer/appointments") public Appointment book(@RequestBody Booking b,Authentication auth){ShopUser owner=current(auth);if(b.petId==null||b.serviceId==null)throw new IllegalArgumentException("Choose a pet and service");Pet p=ownedPet(b.petId,owner.getId());PetService service=services.findById(b.serviceId).orElseThrow(()->new IllegalArgumentException("Service not found"));required(b.date,"Date");required(b.time,"Time");try{LocalDate date=LocalDate.parse(b.date);LocalTime.parse(b.time);if(date.isBefore(LocalDate.now()))throw new IllegalArgumentException("Date cannot be in the past");}catch(java.time.format.DateTimeParseException e){throw new IllegalArgumentException("Enter a valid date and time");}
 if(service instanceof VetConsultation){if(b.doctorId==null||!(users.findById(b.doctorId).orElse(null) instanceof Doctor))throw new IllegalArgumentException("Choose a doctor for a veterinary consultation");}else if(b.doctorId!=null)throw new IllegalArgumentException("Doctor assignment is for veterinary consultations only");Appointment a=new Appointment();a.setOwnerId(owner.getId());a.setCustomerName(owner.getFullName());a.setPetId(p.getId());a.setPetName(p.getName());a.setServiceId(service.getId());a.setService(service.getServiceName());a.setDoctorId(b.doctorId);a.setDate(b.date);a.setTime(b.time);a.setStatus("PENDING");return appointments.save(a);}
 @PatchMapping("/customer/appointments/{id}/cancel") public Appointment cancelMyBooking(@PathVariable Long id,Authentication auth){Appointment a=appointment(id);if(!Objects.equals(a.getOwnerId(),current(auth).getId()))throw new org.springframework.security.access.AccessDeniedException("Not your appointment");workflow.validateTransition(a.getStatus(),"CANCELLED");a.setStatus("CANCELLED");return appointments.save(a);}
 @GetMapping("/doctor/appointments") public List<Map<String,Object>> assigned(Authentication auth){Long id=current(auth).getId();return appointments.findAll().stream().filter(a->Objects.equals(a.getDoctorId(),id)).map(a->{Map<String,Object> row=new LinkedHashMap<>();row.put("appointment",a);row.put("pet",a.getPetId()==null?null:pets.findById(a.getPetId()).orElse(null));return row;}).collect(Collectors.toList());}
 public static class ConsultationUpdate {public String status;public String consultationNotes;public String medicalNotes;}
 @org.springframework.transaction.annotation.Transactional @PatchMapping("/doctor/appointments/{id}") public Appointment updateConsultation(@PathVariable Long id,@RequestBody ConsultationUpdate update,Authentication auth){Appointment a=appointment(id);if(!Objects.equals(a.getDoctorId(),current(auth).getId()))throw new org.springframework.security.access.AccessDeniedException("Not your appointment");if(update.status!=null){workflow.validateTransition(a.getStatus(),update.status);a.setStatus(update.status);}if(update.consultationNotes!=null){if(update.consultationNotes.length()>2000)throw new IllegalArgumentException("Notes too long");a.setConsultationNotes(update.consultationNotes);}if(update.medicalNotes!=null&&a.getPetId()!=null){if(update.medicalNotes.length()>2000)throw new IllegalArgumentException("Notes too long");Pet p=pets.findById(a.getPetId()).orElseThrow(()->new IllegalArgumentException("Pet not found"));p.setMedicalNotes(update.medicalNotes);pets.save(p);}return appointments.save(a);}
 @PatchMapping("/admin/appointments/{id}/status") public Appointment adminStatus(@PathVariable Long id,@RequestBody Map<String,String> body){Appointment a=appointment(id);String next=body.get("status");workflow.validateTransition(a.getStatus(),next);a.setStatus(next);return appointments.save(a);}
 @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Collections.singletonMap("message",e.getMessage()));}
}
